// Card UI languages. Texts are written in the code as this.t(polish, english); every other language looks the English
// text up in TR (generated by tools/gen_i18n.py from i18n/<lang>.json). A text built with values, e.g.
// `cycles ~${n} min`, is stored as the pattern "cycles ~{0} min" and matched at run time.
import { TR } from "./i18n_data";

export const LANGS = ["pl", "en", "cs", "de", "es", "fr", "hu", "it", "nl", "pt", "sk"];
const LOCALES: Record<string, string> = {
  pl: "pl-PL", en: "en-GB", cs: "cs-CZ", de: "de-DE", es: "es-ES", fr: "fr-FR", hu: "hu-HU", it: "it-IT", nl: "nl-NL",
  pt: "pt-PT", sk: "sk-SK",
};
export const locale = (lang: string) => LOCALES[lang] ?? "en-GB";

const esc = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const patterns: Record<string, [RegExp, string][]> = {};
const memo: Record<string, Map<string, string>> = {};

function pats(lang: string) {
  return (patterns[lang] ??= Object.keys(TR[lang] ?? {}).filter((k) => /\{\d+\}/.test(k)).map((k) =>
    [new RegExp("^" + k.split(/\{\d+\}/).map(esc).join("([\\s\\S]*?)") + "$"), TR[lang][k]] as [RegExp, string]));
}

export function translate(lang: string, pl: string, en: string): string {
  if (lang === "pl") return pl;
  const d = TR[lang];
  if (!d) return en;
  const hit = d[en];
  if (hit !== undefined) return hit;
  const m = (memo[lang] ??= new Map());
  const done = m.get(en);
  if (done !== undefined) return done;
  let out = en;
  for (const [re, tpl] of pats(lang)) {
    const g = re.exec(en);
    if (g) { out = tpl.replace(/\{(\d+)\}/g, (_, i) => g[+i + 1] ?? ""); break; }
  }
  if (m.size > 3000) m.clear();
  m.set(en, out);
  return out;
}
